var urlon = {
    version: "1.0.0",
    stringify: function(obj) {
        return urlon.stringifyObject(obj);
    },
    parse: function(str) {
        return urlon.parseToken(urlon.tokenize(str));
    },
    stringifyObject: function(obj, prefix) {
        var parts = [];
        for (var key in obj) {
            parts.push(urlon.stringifyToken(key, obj[key], prefix));
        }
        return parts.join("&");
    },
    stringifyToken: function(key, val, prefix) {
        var pre = prefix ? "" : "$";
        if (Array.isArray(val)) {
            return urlon.stringifyArray(key, val);
        } else if (val && typeof val === "object") {
            return urlon.stringifyObject(val, pre + key + "/");
        } else {
            return pre + key + "=" + urlon.encode(val);
        }
    },
    stringifyArray: function(key, arr) {
        var parts = [];
        for (var i = 0; i < arr.length; i++) {
            parts.push(urlon.stringifyToken(i, arr[i], "$" + key + "/"));
        }
        return parts.join("&");
    },
    encode: function(val) {
        var str = encodeURIComponent(String(val));
        return str.replace(/!/g, "%21").replace(/'/g, "%27").replace(/\(/g, "%28").replace(/\)/g, "%29").replace(/\*/g, "%2A").replace(/%20/g, "+");
    },
    decode: function(str) {
        return decodeURIComponent(str.replace(/\+/g, "%20"));
    },
    tokenize: function(str) {
        var parts = str.split("&");
        var tokens = [];
        for (var i = 0; i < parts.length; i++) {
            var part = parts[i];
            if (!part.length) continue;
            var eq = part.indexOf("=");
            var key, val;
            if (eq === -1) {
                key = part;
                val = "";
            } else {
                key = part.substring(0, eq);
                val = part.substring(eq + 1);
            }
            tokens.push({
                key: key,
                value: urlon.decode(val),
                type: key.indexOf("$") === 0 ? "leaf" : "leaf"
            });
        }
        return tokens;
    },
    parseToken: function(tokens) {
        var result = {};
        for (var i = 0; i < tokens.length; i++) {
            var token = tokens[i];
            var keys = token.key.split("/");
            var current = result;
            for (var j = 0; j < keys.length - 1; j++) {
                var k = keys[j];
                if (!current[k]) {
                    var nextKey = keys[j + 1];
                    current[k] = isNaN(nextKey) ? {} : [];
                }
                current = current[k];
            }
            var lastKey = keys[keys.length - 1];
            var val = token.value;
            var idx = parseInt(lastKey);
            if (current[lastKey] === undefined) {
                current[lastKey] = isNaN(idx) ? val : [val];
            } else if (Array.isArray(current[lastKey])) {
                current[lastKey].push(val);
            } else {
                current[lastKey] = [current[lastKey], val];
            }
        }
        return result;
    }
};